// Persist image-bundled plugin install records into OpenClaw's canonical
// SQLite registry. OpenClaw 2026.7.1-2 no longer treats the legacy
// openclaw.json plugins.installs object as authoritative during startup Doctor
// convergence.

import fs from "node:fs";
import path from "node:path";
import { DatabaseSync } from "node:sqlite";

const INDEX_KEY = "installed-plugin-index";
const INDEX_WARNING =
  "DO NOT EDIT. This file is generated by OpenClaw from plugin manifests, install records, and config policy.";
const RETIRED_OR_BUNDLED_PLUGIN_IDS = [
  "oneclaw-channel",
  "oneclaw-workflows",
  "oneclaw-employee-catalog",
];

const TABLE_SQL = `
CREATE TABLE IF NOT EXISTS installed_plugin_index (
  index_key TEXT NOT NULL PRIMARY KEY,
  version INTEGER NOT NULL,
  host_contract_version TEXT NOT NULL,
  compat_registry_version TEXT NOT NULL,
  migration_version INTEGER NOT NULL,
  policy_hash TEXT NOT NULL,
  generated_at_ms INTEGER NOT NULL,
  refresh_reason TEXT,
  install_records_json TEXT NOT NULL,
  plugins_json TEXT NOT NULL,
  diagnostics_json TEXT NOT NULL,
  warning TEXT,
  updated_at_ms INTEGER NOT NULL
);
`;

function parseInstallRecords(raw) {
  if (typeof raw !== "string" || !raw) return {};
  try {
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return {};
    return Object.fromEntries(Object.entries(parsed).filter(
      ([, record]) => record && typeof record === "object" && !Array.isArray(record),
    ));
  } catch {
    return {};
  }
}

function installRecordsMatch(left, right) {
  return [
    "source",
    "spec",
    "sourcePath",
    "installPath",
    "version",
    "resolvedName",
    "resolvedVersion",
    "resolvedSpec",
  ].every((key) => left[key] === right[key]);
}

export function syncPreinstalledPluginInstallIndex(
  stateDir,
  records,
  { now = Date.now() } = {},
) {
  if (!stateDir || typeof stateDir !== "string") {
    return { ok: false, changed: false, error: "state directory is required" };
  }
  if (!records || typeof records !== "object" || Array.isArray(records)) {
    return { ok: false, changed: false, error: "install records must be an object" };
  }
  if (Object.keys(records).length === 0) {
    return { ok: true, changed: false, skipped: true };
  }

  const sqliteDir = path.join(stateDir, "state");
  const sqlitePath = path.join(sqliteDir, "openclaw.sqlite");
  fs.mkdirSync(sqliteDir, { recursive: true });

  let db;
  try {
    db = new DatabaseSync(sqlitePath);
    db.exec("PRAGMA busy_timeout = 5000;");
    db.exec(TABLE_SQL);
    const row = db.prepare(`
      SELECT install_records_json
        FROM installed_plugin_index
       WHERE index_key = ?
    `).get(INDEX_KEY);

    const merged = row ? parseInstallRecords(row.install_records_json) : {};
    let changed = !row;
    for (const pluginId of RETIRED_OR_BUNDLED_PLUGIN_IDS) {
      if (!Object.hasOwn(merged, pluginId)) continue;
      delete merged[pluginId];
      changed = true;
    }
    for (const [pluginId, record] of Object.entries(records)) {
      const existing = merged[pluginId];
      if (existing && installRecordsMatch(existing, record)) continue;
      merged[pluginId] = record;
      changed = true;
    }

    if (!changed) return { ok: true, changed: false, sqlitePath };
    if (row) {
      db.prepare(`
        UPDATE installed_plugin_index
           SET install_records_json = ?,
               updated_at_ms = ?,
               generated_at_ms = ?
         WHERE index_key = ?
      `).run(JSON.stringify(merged), now, now, INDEX_KEY);
    } else {
      db.prepare(`
        INSERT INTO installed_plugin_index (
          index_key, version, host_contract_version, compat_registry_version,
          migration_version, policy_hash, generated_at_ms, refresh_reason,
          install_records_json, plugins_json, diagnostics_json, warning, updated_at_ms
        ) VALUES (
          ?, 1, 'oneclaw-cloud-managed', 'oneclaw-cloud-managed',
          1, 'oneclaw-cloud-managed', ?, 'source-changed',
          ?, '[]', '[]', ?, ?
        )
      `).run(INDEX_KEY, now, JSON.stringify(merged), INDEX_WARNING, now);
    }
    return { ok: true, changed: true, sqlitePath };
  } catch (err) {
    return { ok: false, changed: false, sqlitePath, error: err.message };
  } finally {
    db?.close();
  }
}
